"use strict";(globalThis.webpackChunkschool_portal||=[]).push([[737],{3674(e){e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"sovereign-school-ai-breakthrough","metadata":{"permalink":"/schoolsample/blog/sovereign-school-ai-breakthrough","source":"@site/blog/2026-08-16-school-ai-breakthrough.md","title":"Sovereign In-Browser AI Tutoring Architecture","description":"This live demonstration introduces a decoupled, zero-cloud architecture designed to deliver sub-second, interactive AI tutoring directly inside school curriculum materials while ensuring complete student data sovereignty.","date":"2026-08-16T00:00:00.000Z","tags":[{"inline":true,"label":"webrtc","permalink":"/schoolsample/blog/tags/webrtc"},{"inline":true,"label":"edtech","permalink":"/schoolsample/blog/tags/edtech"},{"inline":true,"label":"privacy","permalink":"/schoolsample/blog/tags/privacy"},{"inline":true,"label":"ai","permalink":"/schoolsample/blog/tags/ai"},{"inline":true,"label":"zero-cors","permalink":"/schoolsample/blog/tags/zero-cors"}],"readingTime":1.17,"hasTruncateMarker":true,"authors":[{"name":"School AI Team","title":"Core Engineering & Architecture","socials":{},"key":null,"page":null}],"frontMatter":{"slug":"sovereign-school-ai-breakthrough","title":"Sovereign In-Browser AI Tutoring Architecture","authors":[{"name":"School AI Team","title":"Core Engineering & Architecture"}],"tags":["webrtc","edtech","privacy","ai","zero-cors"]},"unlisted":false},"content":"This live demonstration introduces a decoupled, zero-cloud architecture designed to deliver sub-second, interactive AI tutoring directly inside school curriculum materials while ensuring complete student data sovereignty.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n---\\r\\n\\r\\n### Core Architectural Breakthroughs\\r\\n\\r\\n* **Zero-CORS Transport Layer:** By establishing an in-memory WebRTC loopback operating over SCTP and DTLS, the application eliminates standard HTTP preflight latency, reverse-proxy bottlenecks, and cross-origin security restrictions.\\r\\n* **100% Data Sovereignty:** Student prompts, telemetry, and speech synthesis pipelines execute locally without routing unencrypted PII to third-party cloud LLM providers.\\r\\n* **DOM-Decoupled Execution:** The AI networking and streaming engine runs independently from UI rendering cycles, preventing main-thread layout lag and dropped audio frames.\\r\\n* **Universal Embeddability:** A single self-defending JavaScript bundle turns any static documentation platform (Docusaurus, CMS, or LMS) into an interactive AI terminal.\\r\\n\\r\\n---\\r\\n\\r\\n### Institutional Value Proposition\\r\\n\\r\\n| Metric | Traditional Cloud AI SaaS | In-Browser Sovereign Loopback |\\r\\n| :--- | :--- | :--- |\\r\\n| **Data Privacy & GDPR** | High risk (Cloud API egress) | **Zero cloud leakage (Local subnet)** |\\r\\n| **Annual Licensing Cost** | \xa315 \u2013 \xa330 per student/month | **\xa30 API fees (Self-hosted hardware)** |\\r\\n| **Response Latency** | 800 ms \u2013 2,500 ms | **< 20 ms in-memory transport** |\\r\\n| **Voice Synthesis** | Cloud TTS billing tiers | **Native zero-latency Web Speech** |\\r\\n\\r\\n---\\r\\n\\r\\n### How to Test the Demo\\r\\n\\r\\n1. Navigate to the **Lessons** tab in the top navigation bar.\\r\\n2. Select any curriculum topic or enter a custom student prompt.\\r\\n3. Observe real-time frame streaming, live RTT transport counters, and native spoken feedback."}]}}')}}]);